ClipboardHostApiForNativeInterop? pigeon_getInstance_ClipboardHostApi({
  String channelName = defaultInstanceName,
}) => _ClipboardHostApiForNativeInterop.getInstance(channelName: channelName);

class _ClipboardHostApiForNativeInterop
    implements ClipboardHostApiForNativeInterop {
  _ClipboardHostApiForNativeInterop._withRegistrar({
    jni_bridge.ClipboardHostApiRegistrar? jniApi,
    ffi_bridge.ClipboardHostApiSetup? ffiApi,
  }) : _jniApi = jniApi,
       _ffiApi = ffiApi;

  /// Returns instance of ClipboardHostApiForNativeInterop with specified [channelName] if one has been registered.
  ///
  /// Returns the instance registered by this isolate's engine when it is known,
  /// and otherwise the most recent registration.
  static ClipboardHostApiForNativeInterop? getInstance({
    String channelName = defaultInstanceName,
  }) {
    if (Platform.isAndroid) {
      final int? engineId = PlatformDispatcher.instance.engineId;
      final JString jName = channelName.toJString();
      final jni_bridge.ClipboardHostApiRegistrar? link;
      try {
        link = jni_bridge.ClipboardHostApiRegistrar.pigeonResolveInstance(
          engineId ?? _pigeonNoEngineKey,
          _pigeonEngineAffinity ?? _pigeonNoEngineKey,
          jName,
        );
      } finally {
        jName.release();
      }
      if (link == null) {
        _throwNoInstanceError(channelName);
      }
      if (link != null && _pigeonEngineAffinity == null) {
        final int linkEngineKey =
            jni_bridge.ClipboardHostApiRegistrar.pigeonEngineKeyOf(link);
        if (linkEngineKey != _pigeonNoEngineKey &&
            (engineId == null || linkEngineKey < 0)) {
          _pigeonEngineAffinity = linkEngineKey;
          _pigeonUpdateFlutterApiEngineAffinity();
        }
      }
      return _ClipboardHostApiForNativeInterop._withRegistrar(jniApi: link);
    } else if (Platform.isIOS || Platform.isMacOS) {
      final int? engineId = PlatformDispatcher.instance.engineId;
      final ffi_bridge.ClipboardHostApiSetup? link =
          ffi_bridge.ClipboardHostApiSetup.pigeonResolveInstanceWithEngineId(
            engineId ?? _pigeonNoEngineKey,
            affinityKey: _pigeonEngineAffinity ?? _pigeonNoEngineKey,
            name: NSString(channelName),
          );
      if (link == null) {
        _throwNoInstanceError(channelName);
      }
